recipes.code:
{
  "inputs": [
    {
      "id": "hubequity-api-key",
      "type": "promptString",
      "description": "Optional hubq_ API key. Unlocks premium (Pro/Enterprise) tools and raises the rate limit. Omit to run anonymously (60 requests/minute, base tools only).",
      "password": true
    }
  ],
  "servers": {
    "hub-equity": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "hub-equity-mcp@1.0.1"
      ],
      "env": {
        "HUBEQUITY_API_KEY": "${input:hubequity-api-key}"
      }
    }
  }
}
